sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var taskId = current.servicenow_task_id;

    var swbEmailTask = new GlideRecord("x_hsb11_hsbcmss_eh_hsbc_email_case_task");
    swbEmailTask.get(taskId);
    var swbEmailCase = new GlideRecord("x_hsb11_hsbcmss_eh_hsbc_email_case");
    swbEmailCase.get(swbEmailTask.parent);

    if (current.state == "Processed") {
        swbEmailCase.swb_status = "SWB Extract Request Sent Successfully";
        swbEmailCase.swb_id = current.swb_id;
        swbEmailCase.update();
        gs.eventQueue('x_hsb11_hsbcmss_eh.close_email_task', swbEmailTask, "3", current.swb_id.toString());

        /*swbEmailTask.state = "3";
        swbEmailTask.swb_id = current.swb_id; 
        swbEmailTask.work_notes = "Request Completed Successfully";
        swbEmailTask.update();*/
    } else if (current.state == "Error") {
        //swbEmailCase.swb_status = current.error_body;
        swbEmailCase.update();
        gs.eventQueue('x_hsb11_hsbcmss_eh.close_email_task', swbEmailTask, "4", current.error_body.toString());

		// //Create an event in ITID Instance
        // var failureDescription = "HSBC MSS Cash Equities SWB Outbound iQube Widget failure, details of the error are - ServiceNow Reference -" + current.servicenow_task_id.number + " Timestamp : " + current.response_date + " Error code - " + current.error_code + " Error Body - " + current.error_body; // MSSOTIQUBE-1358

        // var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_SWB');

		//MSSOTIQUBE-1358
		if(current.qtrack_id){
			var failureDescription = "Cash Equities SWB Outbound Widget failure, details of the error are - ServiceNow Reference -" + current.servicenow_task_id.number + " Qtrack ID: " + current.qtrack_id + " Timestamp : " + current.response_date + " Error code - " + current.error_code + " Error Body - " + current.error_body; 
			var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_SWB');
		}else{
			failureDescription = "Unstructured Instruction SWB Outbound Widget failure, details of the error are - ServiceNow Reference -" + current.servicenow_task_id.number + " SWB ID: " + current.swb_id + " Timestamp : " + current.response_date + " Error code - " + current.error_code + " Error Body - " + current.error_body; 
			createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_SWB');
		}
		//

        /*swbEmailTask.state = "4";
        swbEmailTask.work_notes = "Request Failed to Complete";
        swbEmailTask.update();*/
    }

})(current, previous);
